pragma solidity >=0.8.0;

contract EventReplayEmptyClobber {
    event Pair(uint256 a, string b);

    uint256 public count;

    function fire() public {
        emit Pair(7, "abc");
        emit Pair(0, "");
        count++;
    }

    function getCount() public view returns (uint256) {
        return count;
    }
}
